// protoc-gen-fieldmap 从 proto 消息与每适配器一份的 YAML spec 生成强类型
// 的字段映射函数，替代 go-wind 生态适配器中手工维护的"配置字段 → 上游
// 选项"样板代码（零值卫语句、类型转换、选项拼装）。
//
// 虽然沿用 protoc-gen-* 命名归入本仓库的生成器家族，但它不是 protoc
// 插件：独立读 proto 源码（protocompile，含全部传递依赖与标准 WKT），
// 不依赖 protoc/buf 管线。
//
// 用法：
//
//	protoc-gen-fieldmap -I conf/proto -spec specs -out .
//
//	-I    proto 包含根，可重复
//	-spec spec 文件或目录（目录取全部 *.yaml/*.yml，一文件一条规则），可重复
//	-out  输出根目录，默认 .
//
// 生成的文件带 "Code generated by protoc-gen-fieldmap. DO NOT EDIT." 头，
// 调整映射规则请编辑 spec 后重新生成。
package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"path/filepath"
)

// release is the current protoc-gen-fieldmap version.
const release = "v0.1.0"

// listFlag 支持重复传参的字符串列表。
type listFlag []string

func (l *listFlag) String() string { return fmt.Sprint(*l) }
func (l *listFlag) Set(v string) error {
	*l = append(*l, v)
	return nil
}

var showVersion = flag.Bool("version", false, "print the version and exit")

func main() {
	var specsFlag, includesFlag listFlag
	outDir := flag.String("out", ".", "output root directory")

	flag.Var(&specsFlag, "spec", "spec file or directory (repeatable)")
	flag.Var(&includesFlag, "I", "proto import root (repeatable)")

	flag.Parse()
	if *showVersion {
		fmt.Printf("protoc-gen-fieldmap %v\n", release)
		return
	}
	if err := run(context.Background(), includesFlag, specsFlag, *outDir); err != nil {
		fmt.Fprintln(os.Stderr, "protoc-gen-fieldmap:", err)
		os.Exit(1)
	}
}

func run(ctx context.Context, includesFlag, specsFlag listFlag, outDir string) error {
	if len(specsFlag) == 0 {
		return fmt.Errorf("no -spec given")
	}
	if len(includesFlag) == 0 {
		return fmt.Errorf("no -I given")
	}

	specs, err := LoadSpecs(specsFlag)
	if err != nil {
		return err
	}

	outs, err := generateAll(ctx, includesFlag, specs)
	if err != nil {
		return err
	}

	for _, out := range outs {
		dst := filepath.Join(outDir, filepath.FromSlash(out.name))
		if dir := filepath.Dir(dst); dir != "." {
			if err := os.MkdirAll(dir, 0o755); err != nil {
				return fmt.Errorf("mkdir %s: %w", dir, err)
			}
		}
		if err := os.WriteFile(dst, out.content, 0o644); err != nil {
			return fmt.Errorf("write %s: %w", dst, err)
		}
		fmt.Printf("protoc-gen-fieldmap: wrote %s\n", dst)
	}
	return nil
}
